import java.util.Scanner;

public class TextDocumentAnalysis3 {
    private static void step(int[] st, char c) {
        int maxL = st[0];
        int nwi = st[1];
        int fp = st[2];
        int fw = st[3];

        if (c == '(') {
            fp++;
            fw = 0;
        } else if (c == ')') {
            if (fp == 1 && fw != 0) {
                nwi++;
            }
            fp--;
            fw = 0;
        } else if (c == '_') {
            if (fp == 1 && fw != 0) {
                nwi++;
            }
            fw = 0;
        } else {
            fw++;
        }

        if (fp == 0) {
            maxL = Math.max(fw, maxL);
        }

        st[0] = maxL;
        st[1] = nwi;
        st[2] = fp;
        st[3] = fw;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        int[] st = { -1, 0, 0, 0 };
        for (int i = 0; i < n; i++) {
            step(st, s.charAt(i));
        }
        System.out.println(st[0] + " " + st[1]);
    }
}
